import React from 'react';
import { Link } from 'react-router-dom';
import Seo from '../components/Seo';
import { ArtBand } from '../components/Art';
import { agenticTestDevelopmentPillar as pillar } from '../content/pillar';
import { solutionSegments } from '../content/solutions';
import { withFunnelParams } from '../utils/funnel';
import './SolutionPage.css';

// Category-level page: what agentic test & development is, the two approaches side by side, and the workflow pages.
// Two illustrations as section backgrounds (ArtBand): ai-test-lab in the hero, ai-bracket-test opening the workflow list.
const [introFirst, ...introMore] = pillar.intro.split(/(?<=\.)\s+/);
const introRest = introMore.join(' ');

const AgenticTestDevelopmentPage = () => (
  <main className="solution-design lx-solution">
    <Seo title={`${pillar.label} | Plotune`} description={pillar.intro} path={pillar.path} />
    <ArtBand as="header" hero priority name="ai-test-lab" alt="An AI assistant running a test lab" className="design-container">
      <h1>{pillar.heroTitle}</h1>
      <p>{introFirst}</p>
      <div className="lx-actions lx-actions-left">
        <Link className="design-button" to={withFunnelParams('/contact')}>Discuss your setup</Link>
        <Link className="design-button secondary" to={withFunnelParams('/nexus')}>Explore Nexus</Link>
      </div>
    </ArtBand>
    <div className="design-container">
      {introRest && <p className="sol-more m-hide">{introRest}</p>}
      <section className="lx-section">
        <div className="lx-head"><h2>Traditional automation vs. an agentic workflow</h2></div>
        <div className="lx-compare">
          <div className="lx-card lx-before">
            <h2>Traditional automation</h2>
            <ul>{pillar.traditional.map((item, i) => <li key={item}><b aria-hidden="true">{i + 1}.</b><span>{item}</span></li>)}</ul>
          </div>
          <div className="lx-card lx-after">
            <h2>The agentic approach</h2>
            <ul>{pillar.agentic.map((item, i) => <li key={item}><b aria-hidden="true">{i + 1}.</b><span>{item}</span></li>)}</ul>
          </div>
        </div>
      </section>

      <section className="lx-section">
        <ArtBand as="div" name="ai-bracket-test" alt="An AI assistant testing a metal bracket" className="sol-band">
          <h2>Explore by workflow</h2>
        </ArtBand>
        <div>
          <div className="sol-links">
            {pillar.segmentSlugs.map((slug) => {
              const segment = solutionSegments[slug];
              if (!segment) return null;
              return (
                <Link key={slug} to={withFunnelParams(`/solutions/${slug}`)} className="lx-card sol-link">
                  <h3>{segment.label}</h3>
                  <p>{segment.heroTitle}</p>
                  <span className="lx-more">Read more →</span>
                </Link>
              );
            })}
          </div>
        </div>
      </section>

      <section className="lx-closing">
        <h2>See the bounded-operation model in practice.</h2>
        <p>Plotune Nexus is the runtime this whole approach is built on.</p>
        <div className="lx-actions">
          <Link className="design-button secondary" to={withFunnelParams('/nexus')}>Explore Nexus</Link>
          <Link className="design-button" to={withFunnelParams('/contact')}>Discuss your setup</Link>
        </div>
      </section>
      <div className="lx-bottom" />
    </div>
  </main>
);

export default AgenticTestDevelopmentPage;
